-- Repair correction UPDATE no-ops and retain saved application-example provenance. No source/archive/ledger/history deletion.
DROP TRIGGER invalidate_naru_correction_entry_update;
CREATE TRIGGER invalidate_naru_correction_entry_update AFTER UPDATE OF id,source_id,source_key,content_hash,payload_json,ready ON catalog_source_entries WHEN OLD.id IS NOT NEW.id OR OLD.source_id IS NOT NEW.source_id OR OLD.source_key IS NOT NEW.source_key OR OLD.content_hash IS NOT NEW.content_hash OR OLD.payload_json IS NOT NEW.payload_json OR OLD.ready IS NOT NEW.ready BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_entry_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.id IN(c.original_source_entry_id,c.corrected_source_entry_id) OR NEW.id IN(c.original_source_entry_id,c.corrected_source_entry_id)); END;
DROP TRIGGER invalidate_naru_correction_source_update;
CREATE TRIGGER invalidate_naru_correction_source_update AFTER UPDATE OF id,series_key,source_file,sha256,archive_json ON catalog_workbook_sources WHEN OLD.id IS NOT NEW.id OR OLD.series_key IS NOT NEW.series_key OR OLD.source_file IS NOT NEW.source_file OR OLD.sha256 IS NOT NEW.sha256 OR OLD.archive_json IS NOT NEW.archive_json BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_source_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId')) OR NEW.id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
DROP TRIGGER invalidate_naru_correction_archive_update;
CREATE TRIGGER invalidate_naru_correction_archive_update AFTER UPDATE OF source_id,sheet_name,row_number,payload_json ON catalog_workbook_sheet_rows WHEN OLD.source_id IS NOT NEW.source_id OR OLD.sheet_name IS NOT NEW.sheet_name OR OLD.row_number IS NOT NEW.row_number OR OLD.payload_json IS NOT NEW.payload_json BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_archive_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.source_id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId')) OR NEW.source_id IN(json_extract(c.proof_json,'$.originalSourceId'),json_extract(c.proof_json,'$.correctedSourceId'))); END;
DROP TRIGGER invalidate_naru_correction_link_update;
CREATE TRIGGER invalidate_naru_correction_link_update AFTER UPDATE OF source_entry_id,word_id,match_kind ON catalog_word_source_links WHEN OLD.source_entry_id IS NOT NEW.source_entry_id OR OLD.word_id IS NOT NEW.word_id OR OLD.match_kind IS NOT NEW.match_kind BEGIN INSERT OR IGNORE INTO catalog_word_source_correction_invalidations SELECT c.id,'invalidate_naru_correction_link_update',CAST(strftime('%s','now') AS INTEGER)*1000 FROM catalog_word_source_corrections c WHERE c.applied_at>0 AND (OLD.word_id=c.word_id OR NEW.word_id=c.word_id); END;
DROP TRIGGER clear_naru_correction_flags;
CREATE TRIGGER clear_naru_correction_flags AFTER INSERT ON catalog_word_source_correction_invalidations BEGIN UPDATE words SET aichi_exam_appeared=0 WHERE id=(SELECT word_id FROM catalog_word_source_corrections WHERE id=NEW.correction_id); END;
DROP TRIGGER refuse_invalidated_naru_correction_flags;
CREATE TRIGGER refuse_invalidated_naru_correction_flags AFTER UPDATE OF aichi_exam_appeared ON words WHEN NEW.aichi_exam_appeared<>0 AND EXISTS(SELECT 1 FROM catalog_word_source_corrections c JOIN catalog_word_source_correction_invalidations i ON i.correction_id=c.id WHERE c.word_id=NEW.id) BEGIN UPDATE words SET aichi_exam_appeared=0 WHERE id=NEW.id; END;
